<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { api, ApiError } from '../../api/client'
import AppIcon from '../../components/AppIcon.vue'

type Option = { id:number; name:string }
type Item = { id:string; title:string; description:string; kind:string; category_name:string; location_name:string; business_status:string; occurred_at:string }
const form = reactive({ q:'', kind:'', category:'', location:'' })
const categories = ref<Option[]>([]); const locations = ref<Option[]>([]); const items = ref<Item[]>([])
const loading = ref(false); const searched = ref(false); const error = ref('')
async function loadMetadata(){ const response=await api<{data:{categories:Option[];locations:Option[]}}>('/items/metadata/'); categories.value=response.data.categories.filter((entry:any)=>entry.parent_id); locations.value=response.data.locations.filter((entry:any)=>entry.parent_id) }
async function search(){ loading.value=true; error.value=''; try{ const params=new URLSearchParams(); Object.entries(form).forEach(([key,value])=>{if(value.trim())params.set(key,value.trim())}); const response=await api<{data:{items:Item[]}}>(`/items/?${params}`); items.value=response.data.items; searched.value=true }catch(reason){error.value=reason instanceof ApiError?reason.message:'搜索失败'}finally{loading.value=false} }
function reset(){ Object.assign(form,{q:'',kind:'',category:'',location:''}); items.value=[]; searched.value=false }
onMounted(()=>loadMetadata().catch(()=>{error.value='筛选项暂时无法加载'}))
</script>

<template><div class="page search-page"><header><p class="eyebrow">P05 · FEDERATED SEARCH</p><h1 class="page-title">全局搜索</h1><p class="page-lead">组合关键词、类型、类别与校园区域；结果只包含当前账号有权读取的字段。</p></header><form class="panel search-form" @submit.prevent="search"><label class="wide"><span>关键词</span><div class="query"><AppIcon name="search"/><input v-model="form.q" placeholder="例如：黑色耳机 图书馆"/></div></label><label><span>线索类型</span><select v-model="form.kind"><option value="">全部</option><option value="LOST">遗失</option><option value="FOUND">招领</option></select></label><label><span>物品类别</span><select v-model="form.category"><option value="">全部</option><option v-for="entry in categories" :key="entry.id" :value="entry.id">{{entry.name}}</option></select></label><label><span>校园区域</span><select v-model="form.location"><option value="">全部</option><option v-for="entry in locations" :key="entry.id" :value="entry.id">{{entry.name}}</option></select></label><footer><button class="button button-ghost" type="button" @click="reset">重置</button><button class="button button-brand" :disabled="loading"><AppIcon name="search"/>{{loading?'搜索中…':'搜索公开线索'}}</button></footer></form><p v-if="error" class="notice error">{{error}}</p><section v-if="searched" class="results"><div class="result-head"><h2>搜索结果</h2><span>{{items.length}} 条（当前页）</span></div><div v-if="items.length" class="result-list"><RouterLink v-for="item in items" :key="item.id" :to="`/items/${item.id}`" class="result panel"><span class="kind">{{item.kind==='LOST'?'遗失':'招领'}}</span><div><h3>{{item.title}}</h3><p>{{item.description}}</p><small>{{item.category_name}} · {{item.location_name}} · {{new Date(item.occurred_at).toLocaleDateString('zh-CN')}}</small></div><span class="status-tag">{{item.business_status}}</span><AppIcon name="arrow"/></RouterLink></div><div v-else class="empty">没有符合条件的可见线索。</div></section></div></template>

<style scoped>.search-page{max-width:1050px}.search-form{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:34px;padding:26px}.wide{grid-column:1/-1}.search-form label>span{display:block;margin-bottom:8px;color:var(--ct-text-muted);font-size:12px}.query{display:flex;align-items:center;gap:10px;padding:0 13px;border:1px solid var(--ct-border);border-radius:11px;background:var(--ct-bg-soft)}input,select{width:100%;padding:12px;color:var(--ct-text);border:1px solid var(--ct-border);border-radius:11px;background:var(--ct-bg-soft)}.query input{border:0;background:transparent;outline:0}.search-form footer{grid-column:1/-1;display:flex;justify-content:flex-end;gap:10px}.notice{padding:13px;border-radius:10px}.error{color:var(--ct-danger);background:rgba(255,111,120,.08)}.results{margin-top:34px}.result-head{display:flex;justify-content:space-between;align-items:center}.result-head span{color:var(--ct-text-muted)}.result-list{display:grid;gap:10px}.result{display:grid;grid-template-columns:auto 1fr auto auto;gap:16px;align-items:center;padding:18px;box-shadow:none}.kind{color:var(--ct-brand);font-size:12px}.result h3,.result p{margin:0}.result p,.result small{display:block;margin-top:6px;color:var(--ct-text-muted)}.empty{padding:55px;border:1px dashed var(--ct-border);border-radius:16px;text-align:center;color:var(--ct-text-muted)}@media(max-width:700px){.search-form{grid-template-columns:1fr}.wide,.search-form footer{grid-column:auto}.result{grid-template-columns:auto 1fr}.result>.status-tag,.result>svg{display:none}}</style>
